def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([3, 3, 3, 3]), fmt([1, 2, 3, 4, 5]), fmt([5, 4, 3, 2, 1]), fmt([-1, -1, 2, -1]), fmt([2, 1]), fmt([1, 2])]
    for n in (2, 3, 4, 5, 8, 12, 20, 30):
        for _ in range(3):
            hi = rng.choice([2, 3, 10, 100])
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)]))
    N = 10 ** 5
    tests.append(fmt([rng.randint(-10 ** 9, 10 ** 9) for _ in range(N)]))
    tests.append(fmt(sorted(rng.randint(-10 ** 9, 10 ** 9) for _ in range(N))))
    tests.append(fmt(sorted((rng.randint(-10 ** 9, 10 ** 9) for _ in range(N)), reverse=True)))
    tests.append(fmt([rng.randint(0, 3) for _ in range(N)]))
    return tests
